export type TranslationKey = keyof (typeof messages)["pt-BR"];

export type AppLanguage = keyof typeof messages;
export type TranslationValues = Record<string, string | number>;

export function translateMessage(language: AppLanguage, key: TranslationKey, values?: TranslationValues): string {
  const message: string = messages[language][key];
  if (!values) return message;
  return message.replace(/\{([^}]+)\}/g, (placeholder, name: string) =>
    Object.prototype.hasOwnProperty.call(values, name) ? String(values[name]) : placeholder,
  );
}
